201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        currentOwner.setAddress(ownerFieldsDto.getAddress());
209	        currentOwner.setCity(ownerFieldsDto.getCity());
210	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
211	        currentOwner.setLastName(ownerFieldsDto.getLastName());
212	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
213	        this.clinicService.saveOwner(currentOwner);
214	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
215	    }
