242	        PetDto petDto = petMapper.toPetDto(pet);
243	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
244	            .buildAndExpand(pet.getId()).toUri());
245	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
246	    }
