249	    @Override
250	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
251	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
252	        if (currentOwner != null) {
253	            Pet currentPet = this.clinicService.findPetById(petId);
254	            if (currentPet != null) {
255	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
256	                currentPet.setName(petFieldsDto.getName());
257	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
258	                this.clinicService.savePet(currentPet);
259	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
260	            }
261	        }
262	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	    }
