294	    /**
295	     * The maximum number of owners permitted per city. Owner creation is rejected once the
296	     * owner's city already contains this many owners.
297	     */
298	    private static final int MAX_OWNERS_PER_CITY = 50;
299	
300	    /**
301	     * Counts how many existing owners live in the given city, compared case-insensitively.
302	     * This is evaluated before the new owner is persisted, so the owner being created is not
303	     * included in the count.
304	     *
305	     * @param city the new owner's city
306	     * @return the number of existing owners in that city
307	     */
308	    private int countOwnersInCity(String city) {
309	        int count = 0;
310	        for (Owner existing : this.clinicService.findAllOwners()) {
311	            if (city.equalsIgnoreCase(existing.getCity())) {
312	                count++;
313	            }
314	        }
315	        return count;
316	    }
317	
318	    /**
319	     * The maximum number of owners that may be created in a single business day. Owner
320	     * creation is rejected once this many owners already fall on the new owner's adjusted
321	     * business day {@code registrationDate}.
322	     */
323	    private static final int MAX_OWNERS_PER_DAY = 100;
324	
325	    /**
326	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
327	     * to the following Monday, while a weekday is returned unchanged.
328	     *
329	     * @param date the date to adjust
330	     * @return the same date if it is a weekday, otherwise the following Monday
331	     */
332	    private LocalDate toBusinessDay(LocalDate date) {
333	        DayOfWeek dayOfWeek = date.getDayOfWeek();
334	        if (dayOfWeek == DayOfWeek.SATURDAY) {
335	            return date.plusDays(2);
336	        }
337	        if (dayOfWeek == DayOfWeek.SUNDAY) {
338	            return date.plusDays(1);
339	        }
340	        return date;
341	    }
342	
343	    /**
344	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
345	     * registrationDate} rolls forward to the same business day. This is evaluated before the
346	     * new owner is persisted, so the owner being created is not included in the count.
347	     *
348	     * @param businessDay the adjusted business day to count against
349	     * @return the number of existing owners registered on that business day
350	     */
351	    private int countOwnersRegisteredOn(LocalDate businessDay) {
352	        int count = 0;
353	        for (Owner existing : this.clinicService.findAllOwners()) {
354	            LocalDate existingDate = existing.getRegistrationDate();
355	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
356	                count++;
357	            }
358	        }
359	        return count;
360	    }
361	
362	    /**
363	     * The number of owners that may be created on a single business day before a bulk-signup
364	     * warning is raised. Once more than this many owners already fall on the current business
365	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
366	     */
367	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
368	
369	    /**
370	     * Reports whether an unusually high number of owners have been created for today's business
371	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
372	     * the business day that {@code LocalDate.now()} rolls forward to.
373	     *
374	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
375	     */
376	    private boolean isBulkSignupDay() {
377	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
378	    }
379	
380	    /**
381	     * Builds the customer code for a newly created owner, formatted
382	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
383	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
384	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
385	     * first eight upper-case hex characters of the SHA-256 digest of
386	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
387	     * stable for a given telephone and last name rather than dependent on creation order.
388	     *
389	     * @param postcode            the owner's postcode (may be {@code null})
390	     * @param normalizedTelephone the owner's normalized E.164 telephone
391	     * @param lastName            the owner's last name
392	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
393	     */
394	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
395	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
396	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
397	    }
398	
399	    /**
400	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
401	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
402	     *
403	     * @param source the string to hash
404	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
405	     */
406	    private static String sha256Hex8(String source) {
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256")
409	                .digest(source.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder hex = new StringBuilder(digest.length * 2);
411	            for (byte b : digest) {
412	                hex.append(String.format("%02x", b));
413	            }
414	            return hex.substring(0, 8).toUpperCase();
415	        } catch (NoSuchAlgorithmException e) {
416	            throw new IllegalStateException("SHA-256 not available", e);
417	        }
418	    }
419	
420	    /**
421	     * Builds the membership number for a newly created owner, formatted
422	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
423	     * customer code and {@code YY} is the last two digits of the owner's registration
424	     * date year, zero-padded to two digits.
425	     *
426	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
427	     * @param registrationDate the owner's registration date
428	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
429	     */
430	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
431	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
432	    }
433	
434	    /**
435	     * Counts how many existing owners share the given first and last name, compared
436	     * case-insensitively. This is evaluated before the new owner is persisted, so the
437	     * owner being created is not included in the count.
438	     *
439	     * @param firstName the new owner's first name
440	     * @param lastName  the new owner's last name
441	     * @return the number of existing owners with the same first and last name
442	     */
443	    private int countNamesakes(String firstName, String lastName) {
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (firstName.equalsIgnoreCase(existing.getFirstName())
447	                && lastName.equalsIgnoreCase(existing.getLastName())) {
448	                count++;
449	            }
450	        }
451	        return count;
452	    }
453	
454	    /**
455	     * Canonical expansions applied to common street-type abbreviations during address
456	     * normalization. Keys and values are upper-cased so the lookup runs after the address
457	     * has itself been upper-cased.
458	     */
459	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
460	        "ST", "STREET",
461	        "RD", "ROAD",
462	        "AVE", "AVENUE");
463	
464	    /**
465	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
466	     * every run of internal whitespace is collapsed to a single space, the result is
467	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
468	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
469	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
470	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
471	     * returned and compared for household duplicates; an address that is blank once
472	     * normalized fails the required-field check.
473	     *
474	     * @param address the raw address value supplied by the client
475	     * @return the normalized address (empty string when {@code address} is null or blank)
476	     */
477	    private static String normalizeAddress(String address) {
478	        if (address == null) {
479	            return "";
480	        }
481	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
482	        if (collapsed.isEmpty()) {
483	            return "";
484	        }
485	        StringBuilder normalized = new StringBuilder(collapsed.length());
486	        for (String token : collapsed.split(" ")) {
487	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
488	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
489	            if (normalized.length() > 0) {
490	                normalized.append(' ');
491	            }
492	            normalized.append(expanded != null ? expanded : token);
493	        }
494	        return normalized.toString();
495	    }
496	
497	    /**
498	     * Normalizes a last name or address for household-duplicate comparison: leading and
499	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
500	     * single space and the result is lower-cased. Two owners are considered to share a
501	     * household when both their last names and addresses produce the same key.
502	     *
503	     * @param value the raw last name or address value
504	     * @return the normalized comparison key (empty string when {@code value} is null)
505	     */
506	    private static String householdKey(String value) {
507	        if (value == null) {
508	            return "";
509	        }
510	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
511	    }
512	
513	    /**
514	     * Derives the stable shared household identifier for the given normalized last name
515	     * and address keys. The identifier is deterministic — the same household (same
516	     * {@link #householdKey normalized} last name and address) always maps to the same
517	     * value — so every owner who joins a household is assigned an identical id. It is the
518	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
519	     * '<lastNameKey>|<addressKey>'}.
520	     *
521	     * @param lastNameKey the normalized last name key
522	     * @param addressKey  the normalized address key
523	     * @return the shared household identifier
524	     */
525	    private static String householdId(String lastNameKey, String addressKey) {
526	        String source = lastNameKey + "|" + addressKey;
527	        try {
528	            byte[] digest = MessageDigest.getInstance("SHA-256")
529	                .digest(source.getBytes(StandardCharsets.UTF_8));
530	            StringBuilder hex = new StringBuilder(digest.length * 2);
531	            for (byte b : digest) {
532	                hex.append(String.format("%02x", b));
533	            }
534	            return hex.substring(0, 12).toUpperCase();
535	        } catch (NoSuchAlgorithmException e) {
536	            throw new IllegalStateException("SHA-256 not available", e);
537	        }
538	    }
539	
540	    /**
541	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
542	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
543	     * possible duplicate when an existing owner shares its last name (compared
544	     * case-insensitively with collapsed whitespace) and its postcode while having a
545	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
546	     * existing owner's id. When several existing owners match, the one with the lowest id
547	     * is chosen so the result is deterministic. When no such owner exists — or the new
548	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
549	     * and no matching id is recorded.
550	     *
551	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
552	     */
553	    private void applyPossibleDuplicate(Owner owner) {
554	        owner.setPossibleDuplicate(false);
555	        if (owner.getPostcode() == null) {
556	            return;
557	        }
558	        String lastNameKey = householdKey(owner.getLastName());
559	        Owner match = null;
560	        for (Owner existing : this.clinicService.findAllOwners()) {
561	            if (lastNameKey.equals(householdKey(existing.getLastName()))
562	                && owner.getPostcode().equals(existing.getPostcode())
563	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
564	                if (match == null || (existing.getId() != null
565	                    && existing.getId() < match.getId())) {
566	                    match = existing;
567	                }
568	            }
569	        }
570	        if (match != null) {
571	            owner.setPossibleDuplicate(true);
572	            owner.setPossibleDuplicateOf(match.getId());
573	        }
574	    }
575	
576	    /**
577	     * Builds the derived duplicate-detection identity key from an owner's normalized
578	     * telephone, email and household id, formatted {@code
579	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
580	     * duplicates only when their whole identity keys are equal; because the telephone is
581	     * part of the key, members of the same household with different telephones produce
582	     * different keys and are both allowed.
583	     *
584	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
585	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
586	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
587	     * @return the identity key string
588	     */
589	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
590	        return (normalizedTelephone == null ? "" : normalizedTelephone)
591	            + "|" + (email == null ? "" : email)
592	            + "|" + (householdId == null ? "" : householdId);
593	    }
594	
595	    /**
596	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
597	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
598	     * {@code null} when the owner has no email.
599	     *
600	     * @param email the existing owner's stored email (may be {@code null})
601	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
602	     */
603	    private static String emailForKey(String email) {
604	        return email == null ? null : email.trim().toLowerCase();
605	    }
606	
607	    /**
608	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
609	     * and brackets are stripped. When the number already carries a leading {@code '+'}
610	     * and country code these are kept; a number written in national trunk form (a leading
611	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
612	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
613	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
614	     * after the {@code '+'}, and its national-number length must be valid for the detected
615	     * country code (see {@link #hasValidNationalLength}).
616	     *
617	     * @param telephone the raw telephone value supplied by the client
618	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
619	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
620	     */
621	    private static String toE164(String telephone) {
622	        if (telephone == null) {
623	            return null;
624	        }
625	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
626	        String digits;
627	        if (cleaned.startsWith("+")) {
628	            digits = cleaned.substring(1);
629	        } else if (cleaned.startsWith("0")) {
630	            digits = "61" + cleaned.substring(1);
631	        } else {
632	            digits = "1" + cleaned;
633	        }
634	        if (!digits.matches("[0-9]{8,15}")) {
635	            return null;
636	        }
637	        if (!hasValidNationalLength(digits)) {
638	            return null;
639	        }
640	        return "+" + digits;
641	    }
642	
643	    /**
644	     * Validates the national-number length of an E.164 digit string against its country
645	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
646	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
647	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
648	     *
649	     * @param digits the E.164 digits (without the leading {@code '+'})
650	     * @return {@code true} when the national-number length is valid for the country code
651	     */
652	    private static boolean hasValidNationalLength(String digits) {
653	        if (digits.startsWith("61")) {
654	            return digits.length() - 2 == 9;
655	        }
656	        if (digits.startsWith("1")) {
657	            return digits.length() - 1 == 10;
658	        }
659	        return true;
660	    }
661	
662	    /**
663	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
664	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
665	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
666	     */
667	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
668	        "NSW", new int[] {2000, 2099},
669	        "VIC", new int[] {3000, 3099},
670	        "QLD", new int[] {4000, 4099});
671	
672	    /**
673	     * Validates an owner's postcode for creation. A postcode is only ever validated when
674	     * present (an absent postcode is optional and accepted). When present it must be exactly
675	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
676	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
677	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
678	     *
679	     * @param postcode the supplied postcode (never {@code null} here)
680	     * @param city     the owner's city, used to derive the region
681	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
682	     *         (signalling a 400 Bad Request)
683	     */
684	    private static boolean isValidPostcode(String postcode, String city) {
685	        if (!postcode.matches("[0-9]{4}")) {
686	            return false;
687	        }
688	        int[] range = REGION_POSTCODES.get(
689	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
690	        if (range == null) {
691	            return true;
692	        }
693	        int value = Integer.parseInt(postcode);
694	        return value >= range[0] && value <= range[1];
695	    }
696	
697	    /**
698	     * Normalizes an owner email for creation. A present email must be a syntactically
699	     * valid address; the returned value is lower-cased.
700	     *
701	     * @param email the raw email value supplied by the client (never {@code null} here)
702	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
703	     *         address (signalling a 400 Bad Request)
704	     */
705	    private static String normalizeEmail(String email) {
706	        String trimmed = email.trim();
707	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
708	            return null;
709	        }
710	        return trimmed.toLowerCase();
711	    }
712	}
